package com.portal.app

object Scripts {
    val ZOOM_JS = """(function(){var m=document.querySelector('meta[name=viewport]');if(m){var c=(m.getAttribute('content')||'').replace(/,?\s*(maximum-scale|minimum-scale|user-scalable)\s*=\s*[^,]*/gi,'');m.setAttribute('content',c+', maximum-scale=10, minimum-scale=0.25, user-scalable=yes');}})();"""
    val IMG_JS = """(function(){if(!document.contentType||document.contentType.indexOf('image/')!==0)return;var m=document.querySelector('meta[name=viewport]');if(!m){m=document.createElement('meta');m.name='viewport';document.head.appendChild(m);}m.setAttribute('content','width=device-width,initial-scale=1,minimum-scale=0.1,maximum-scale=10,user-scalable=yes');var i=document.querySelector('img');if(i){i.style.cssText='max-width:100vw;max-height:100vh;width:auto;height:auto;object-fit:contain;display:block;margin:auto;';}document.body.style.cssText='margin:0;background:#000;';})();"""
    val MEDIA_JS = """(function(){if(window.__ab)return;window.__ab=1;document.addEventListener('contextmenu',function(e){var v=e.target.closest?e.target.closest('video'):null;if(!v&&document.elementsFromPoint){var els=document.elementsFromPoint(e.clientX,e.clientY);for(var i=0;i<els.length;i++){if(els[i].tagName=='VIDEO'){v=els[i];break;}}}if(v){AnimeBridge.media('video',v.currentSrc||v.src||'');e.preventDefault();}},true);})();"""
    val FRAME_JS = "(function(){if(window.__animeT)return;window.__animeT=1;var seekTo=-1,sent=false;function post(o){try{AnimeTime.postMessage(JSON.stringify(o));}catch(e){}}try{AnimeTime.onmessage=function(ev){var m=String(ev.data);if(m.indexOf('seek:')===0){seekTo=parseFloat(m.substring(5));}};}catch(e){}setInterval(function(){var v=document.querySelector('video');if(!v)return;if(v.readyState>0&&isFinite(v.duration)&&v.duration>0){if(!sent){sent=true;post({r:1,d:v.duration});}if(seekTo>=0){v.currentTime=Math.min(seekTo,v.duration-1);seekTo=-1;}if(v.currentTime>0)post({t:v.currentTime,d:v.duration});}},1000);})();"
    val DARK_ON = "(function(){var s=document.getElementById('__dk');if(!s){s=document.createElement('style');s.id='__dk';s.textContent='html{filter:invert(1) hue-rotate(180deg)!important;background:#fff} img,picture,video,canvas,iframe{filter:invert(1) hue-rotate(180deg)!important}';(document.head||document.documentElement).appendChild(s);}})();"
    val DARK_OFF = "(function(){var s=document.getElementById('__dk');if(s)s.remove();})();"
    val STATE_JS = "(function(){var v=document.querySelector('video');return JSON.stringify({y:Math.round(window.scrollY||0),t:(v&&isFinite(v.currentTime))?v.currentTime:-1});})()"
}
